  FDPE \pcie_rst_2ff_reg[0] 
       (.C(user_clk),
        .CE(1'b1),
        .D(\pcie_rst_2ff[2]_i_1_n_0 ),
        .PRE(\pcie_rst_2ff[2]_i_1_n_0 ),
        .Q(pcie_rst_2ff[0]));
  (* KEEP = "yes" *) 
  FDPE \pcie_rst_2ff_reg[1] 
       (.C(user_clk),
        .CE(1'b1),
        .D(\pcie_rst_2ff[2]_i_1_n_0 ),
        .PRE(\pcie_rst_2ff[2]_i_1_n_0 ),
        .Q(pcie_rst_2ff[1]));
  (* KEEP = "yes" *) 
  FDPE \pcie_rst_2ff_reg[2] 
       (.C(user_clk),
        .CE(1'b1),
        .D(\pcie_rst_2ff[2]_i_1_n_0 ),
        .PRE(\pcie_rst_2ff[2]_i_1_n_0 ),
        .Q(pcie_rst_2ff[2]));
endmodule
